from PIL import Image
im = Image.open('barcode.png').convert('RGB')
W,H = im.size
px = im.load()
def avg(x):
    r=g=b=0
    for y in range(H):
        p=px[x,y]; r+=p[0]; g+=p[1]; b+=p[2]
    return (r/H,g/H,b/H)
print("tail x=900..999:")
for x in range(900,1000,2):
    c=avg(x); print(f"x={x} ({c[0]:.0f},{c[1]:.0f},{c[2]:.0f})")
print("\nblue region x=415..450:")
for x in range(415,450):
    c=avg(x); print(f"x={x} ({c[0]:.0f},{c[1]:.0f},{c[2]:.0f})")
print("\npale region x=115..130:")
for x in range(115,130):
    c=avg(x); print(f"x={x} ({c[0]:.0f},{c[1]:.0f},{c[2]:.0f})")
EOF

