import urllib.request, re
urls = {
 "Detachment": "https://en.wikipedia.org/wiki/Detachment_(film)",
 "WarriorsWay": "https://en.wikipedia.org/wiki/The_Warrior%27s_Way",
}
# Extract poster thumb URLs from the fetched pages
for name,u in urls.items():
    try:
        req=urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'})
        html=urllib.request.urlopen(req, timeout=20).read().decode('utf8','ignore')
        m=re.findall(r'(//upload\.wikimedia\.org/wikipedia/en/thumb/[^\s"]+?\.jpg)/', html)
        print(name, m[:3])
    except Exception as e:
        print(name, "ERR", e)
EOF

