{"command": "python3 << 'EOF'
import urllib.request, re
def search(site, q):
    u=f"https://{site}/?s={q}"
    try:
        req=urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'})
        html=urllib.request.urlopen(req, timeout=25).read().decode('utf8','ignore')
        links=set(re.findall(r'href="(https?://[^"]*?%s[^"]*?)"'%q.replace(' ','+'), html, re.I))
        links=[l for l in links if site in l and ('/20' in l or q.split()[0].lower() in l.lower())]
        print(site, q, "->", list(links)[:8])
        if not links:
            # fallback: find any post links with the word
            links2=set(re.findall(r'href="(https?://[^"]*)"', html))
            hits=[l for l in links2 if q.split()[0].lower() in l.lower() and site in l]
            print("  fallback:", list(hits)[:8])
    except Exception as e:
        print(site, q, "ERR", repr(e)[:100])

for q in ["detachment","leaves+of+grass","paris+je","warriors-way","georgia+rule","rebound"]:
    search("movie-screencaps.com", q)
EOF"}

