        levels[idx]=dict(w=int(f[0]),h=int(f[1]),cols=int(f[3]),rows=int(f[4]),name=f[6],sigh=f[-1])
    return base, levels

def thumbs_for(vid, level=1):
    spec,dur=storyboard(vid)
    if not spec: return [],0
    base,levels=parse_spec(spec)
    info=levels[level]
    thumbs=[]
    n=0
    while n<12:
        b=base.replace("$L",str(level))
        fname = "default.jpg" if info['name']=='default' else (info['name'].replace("$M",str(n))+".jpg" if "$M" in info['name'] else f"M{n}.jpg")
        u=b.replace("$N", fname) + "&sigh=" + info['sigh']
        try:
            req=urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'})
            data=urllib.request.urlopen(req, timeout=30).read()
        except Exception as e:
            break
        img=Image.open(io.BytesIO(data)).convert('RGB')
        cols,rows=info['cols'],info['rows']
        tw,th=img.width//cols, img.height//rows
        got=0
        for r in range(rows):
            for c in range(cols):
                tile=img.crop((c*tw, r*th, (c+1)*tw, (r+1)*th))
                # skip blank black tiles (padding) - check variance
                small=tile.resize((8,8))
                px=list(small.getdata())
                if max(max(p) for p in px)-min(min(p) for p in px)==0 and sum(px[0])/3 < 12:
                    continue
                thumbs.append(tile); got+=1
        n+=1
    return thumbs, dur

