import urllib.request, json, urllib.parse, io, os, pickle
from PIL import Image
import colorsys, statistics

CACHE="/tmp/ia/cache.pkl"
def get(u):
    req=urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=45).read()

def thumbs_for(ident, cache_dir):
    os.makedirs(cache_dir, exist_ok=True)
    m=json.loads(get(f"https://archive.org/metadata/{ident}").decode('utf8','ignore'))
    names=sorted([f['name'] for f in m.get('files',[]) if '.thumbs/' in f.get('name','')],
                 key=lambda n: int(n.rsplit('_',1)[1].split('.')[0]))
    imgs=[]
    for n in names:
        fn=os.path.join(cache_dir, os.path.basename(n))
        if os.path.exists(fn):
            imgs.append(Image.open(fn).convert('RGB')); continue
        try:
            data=get(f"https://archive.org/download/{ident}/"+urllib.parse.quote(n))
            open(fn,'wb').write(data)
            imgs.append(Image.open(io.BytesIO(data)).convert('RGB'))
        except Exception:
            pass
    return imgs

if os.path.exists(CACHE):
    cache=pickle.load(open(CACHE,'rb'))
else:
    cache={}
for ident, cd in [("leaves-of-grass-2009-dvdrip","/tmp/ia/leaves")]:
    if ident not in cache:
        cache[ident]=thumbs_for(ident, cd)
        pickle.dump(cache, open(CACHE,'wb'))
print("leaves thumbs:", len(cache["leaves-of-grass-2009-dvdrip"]))
EOF

